    private WebFlightNativeStabilityHostCases(){}
    private static void check(boolean value,String reason){assertions++;if(!value)throw new AssertionError(reason);}
    private static void reject(Work work)throws Exception{
        boolean rejected=false;try{work.run();}catch(IllegalArgumentException|org.json.JSONException expected){rejected=true;}
        check(rejected,"expected bounded production predicate rejection");
    }
    private static void test(Sink sink,String name,Work work)throws Exception{
        int old=assertions;work.run();sink.passed(name,assertions-old);
    }
    private static JSONObject copy(JSONObject value)throws Exception{return new JSONObject(value.toString());}
    private static JSONArray copy(JSONArray value)throws Exception{return new JSONArray(value.toString());}
    private static String hash(byte[] bytes)throws Exception{
        StringBuilder s=new StringBuilder();for(byte b:MessageDigest.getInstance("SHA-256").digest(bytes))
            s.append(String.format(java.util.Locale.ROOT,"%02x",b&255));return s.toString();
    }
    private static JSONObject input()throws Exception{
        StringBuilder text=new StringBuilder();for(String part:INPUT_B64)text.append(part);
        byte[] compressed=Base64.getDecoder().decode(text.toString());ByteArrayOutputStream out=new ByteArrayOutputStream();
        try(GZIPInputStream stream=new GZIPInputStream(new ByteArrayInputStream(compressed))){
            byte[] buffer=new byte[4096];int n;while((n=stream.read(buffer))!=-1){
                if(out.size()+n>342642)throw new AssertionError("bounded pinned replay bytes");out.write(buffer,0,n);
            }
        }
        byte[] bytes=out.toByteArray();if(bytes.length!=342642||!INPUT_SHA.equals(hash(bytes)))
            throw new AssertionError("complete actual replay input SHA differs");
        JSONObject value=new JSONObject(new String(bytes,StandardCharsets.UTF_8));
        for(String pair:new String[]{"actual_dom_a:dom_a_sha256","actual_dom_b:dom_b_sha256",
                "before2_raw:before2_sha256","before3_raw:before3_sha256"}){
            String[] p=pair.split(":");
            if(!value.getString(p[1]).equals(hash(value.getString(p[0]).getBytes(StandardCharsets.UTF_8))))
                throw new AssertionError("actual raw source SHA differs");
        }return value;
    }
