    private static JSONObject observationInput()throws Exception{
        StringBuilder encoded=new StringBuilder();for(String part:OBSERVATION_INPUT_B64)encoded.append(part);
        byte[] compressed=Base64.getDecoder().decode(encoded.toString());ByteArrayOutputStream out=new ByteArrayOutputStream();
        try(GZIPInputStream stream=new GZIPInputStream(new ByteArrayInputStream(compressed))){
            byte[] buffer=new byte[4096];int n;while((n=stream.read(buffer))!=-1){
                if(out.size()+n>OBSERVATION_INPUT_BYTES)throw new AssertionError("bounded actual Flight56 replay input");
                out.write(buffer,0,n);
            }
        }
        byte[] raw=out.toByteArray();
        if(raw.length!=OBSERVATION_INPUT_BYTES||!OBSERVATION_INPUT_SHA.equals(hash(raw)))
            throw new AssertionError("actual Flight56 replay input SHA differs");
        JSONObject value=new JSONObject(new String(raw,StandardCharsets.UTF_8));
        JSONArray originals=value.getJSONArray("originals");
        if(originals.length()!=4)throw new AssertionError("two original scope files and two complete FD records required");
        for(int i=0;i<originals.length();i++){
            JSONObject original=originals.getJSONObject(i);byte[] bytes=original.getString("raw_utf8").getBytes(StandardCharsets.UTF_8);
            if(bytes.length!=original.getInt("bytes")||!hash(bytes).equals(original.getString("sha256")))
                throw new AssertionError("Flight56 original full bytes changed");
        }
        if(value.getBoolean("original_full_native_arrays_were_archived")||!value.getBoolean("full_native_fixture_is_synthetic"))
            throw new AssertionError("unarchived full native traversal must remain explicitly synthetic");
        return value;
    }
